INSERT INTO `regulation_article` (`regulation_id`, `article_no`, `content`) VALUES
((SELECT id FROM regulation WHERE title='中华人民共和国民法典' LIMIT 1), '第一条', '为了保护民事主体的合法权益，调整民事关系，维护社会和经济秩序，适应中国特色社会主义发展要求，弘扬社会主义核心价值观，根据宪法，制定本法。'),
((SELECT id FROM regulation WHERE title='中华人民共和国民法典' LIMIT 1), '第二条', '民法调整平等主体的自然人、法人和非法人组织之间的人身关系和财产关系。'),
((SELECT id FROM regulation WHERE title='中华人民共和国民法典' LIMIT 1), '第三条', '民事主体的人身权利、财产权利以及其他合法权益受法律保护，任何组织或者个人不得侵犯。'),
((SELECT id FROM regulation WHERE title='中华人民共和国民法典' LIMIT 1), '第五条', '民事主体从事民事活动，应当遵循自愿原则，按照自己的意思设立、变更、终止民事法律关系。'),
((SELECT id FROM regulation WHERE title='中华人民共和国民法典' LIMIT 1), '第六条', '民事主体从事民事活动，应当遵循公平原则，合理确定各方的权利和义务。'),
((SELECT id FROM regulation WHERE title='中华人民共和国民法典' LIMIT 1), '第七条', '民事主体从事民事活动，应当遵循诚信原则，秉持诚实，恪守承诺。'),
((SELECT id FROM regulation WHERE title='中华人民共和国民法典' LIMIT 1), '第八条', '民事主体从事民事活动，不得违反法律，不得违背公序良俗。'),
((SELECT id FROM regulation WHERE title='中华人民共和国民法典' LIMIT 1), '第一百四十三条', '具备下列条件的民事法律行为有效：（一）行为人具有相应的民事行为能力；（二）意思表示真实；（三）不违反法律、行政法规的强制性规定，不违背公序良俗。'),
((SELECT id FROM regulation WHERE title='中华人民共和国民法典' LIMIT 1), '第五百七十七条', '当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任。'),
((SELECT id FROM regulation WHERE title='中华人民共和国民法典' LIMIT 1), '第一千零七十六条', '夫妻双方自愿离婚的，应当签订书面离婚协议，并亲自到婚姻登记机关申请离婚登记。离婚协议应当载明双方自愿离婚的意思表示和对子女抚养、财产以及债务处理等事项协商一致的意见。');
INSERT INTO `regulation_article` (`regulation_id`, `article_no`, `content`) VALUES
((SELECT id FROM regulation WHERE title='中华人民共和国劳动合同法' LIMIT 1), '第三条', '订立劳动合同，应当遵循合法、公平、平等自愿、协商一致、诚实信用的原则。依法订立的劳动合同具有约束力，用人单位与劳动者应当履行劳动合同约定的义务。'),
((SELECT id FROM regulation WHERE title='中华人民共和国劳动合同法' LIMIT 1), '第十条', '建立劳动关系，应当订立书面劳动合同。已建立劳动关系，未同时订立书面劳动合同的，应当自用工之日起一个月内订立书面劳动合同。用人单位与劳动者在用工前订立劳动合同的，劳动关系自用工之日起建立。'),
((SELECT id FROM regulation WHERE title='中华人民共和国劳动合同法' LIMIT 1), '第十九条', '劳动合同期限三个月以上不满一年的，试用期不得超过一个月；劳动合同期限一年以上不满三年的，试用期不得超过二个月；三年以上固定期限和无固定期限的劳动合同，试用期不得超过六个月。同一用人单位与同一劳动者只能约定一次试用期。以完成一定工作任务为期限的劳动合同或者劳动合同期限不满三个月的，不得约定试用期。'),
((SELECT id FROM regulation WHERE title='中华人民共和国劳动合同法' LIMIT 1), '第三十六条', '用人单位与劳动者协商一致，可以解除劳动合同。'),
((SELECT id FROM regulation WHERE title='中华人民共和国劳动合同法' LIMIT 1), '第三十八条', '用人单位有下列情形之一的，劳动者可以解除劳动合同：（一）未按照劳动合同约定提供劳动保护或者劳动条件的；（二）未及时足额支付劳动报酬的；（三）未依法为劳动者缴纳社会保险费的；（四）用人单位的规章制度违反法律、法规的规定，损害劳动者权益的；（五）因本法第二十六条第一款规定的情形致使劳动合同无效的；（六）法律、行政法规规定劳动者可以解除劳动合同的其他情形。'),
((SELECT id FROM regulation WHERE title='中华人民共和国劳动合同法' LIMIT 1), '第四十七条', '经济补偿按劳动者在本单位工作的年限，每满一年支付一个月工资的标准向劳动者支付。六个月以上不满一年的，按一年计算；不满六个月的，向劳动者支付半个月工资的经济补偿。月工资是指劳动者在劳动合同解除或者终止前十二个月的平均工资。'),
((SELECT id FROM regulation WHERE title='中华人民共和国劳动合同法' LIMIT 1), '第五十条', '用人单位应当在解除或者终止劳动合同时出具解除或者终止劳动合同的证明，并在十五日内为劳动者办理档案和社会保险关系转移手续。劳动者应当按照双方约定，办理工作交接。用人单位依照本法有关规定应当向劳动者支付经济补偿的，在办结工作交接时支付。'),
((SELECT id FROM regulation WHERE title='中华人民共和国劳动合同法' LIMIT 1), '第八十二条', '用人单位自用工之日起超过一个月不满一年未与劳动者订立书面劳动合同的，应当向劳动者每月支付二倍的工资。用人单位违反本法规定不与劳动者订立无固定期限劳动合同的，自应当订立无固定期限劳动合同之日起向劳动者每月支付二倍的工资。');
INSERT INTO `regulation_article` (`regulation_id`, `article_no`, `content`) VALUES
((SELECT id FROM regulation WHERE title='中华人民共和国劳动法' LIMIT 1), '第三条', '劳动者享有平等就业和选择职业的权利、取得劳动报酬的权利、休息休假的权利、获得劳动安全卫生保护的权利、接受职业技能培训的权利、享受社会保险和福利的权利、提请劳动争议处理的权利以及法律规定的其他劳动权利。劳动者应当完成劳动任务，提高职业技能，执行劳动安全卫生规程，遵守劳动纪律和职业道德。'),
((SELECT id FROM regulation WHERE title='中华人民共和国劳动法' LIMIT 1), '第三十六条', '国家实行劳动者每日工作时间不超过八小时、平均每周工作时间不超过四十四小时的工时制度。'),
((SELECT id FROM regulation WHERE title='中华人民共和国劳动法' LIMIT 1), '第四十四条', '有下列情形之一的，用人单位应当按照下列标准支付高于劳动者正常工作时间工资的工资报酬：（一）安排劳动者延长工作时间的，支付不低于工资的百分之一百五十的工资报酬；（二）休息日安排劳动者工作又不能安排补休的，支付不低于工资的百分之二百的工资报酬；（三）法定休假日安排劳动者工作的，支付不低于工资的百分之三百的工资报酬。');
INSERT INTO `regulation_article` (`regulation_id`, `article_no`, `content`) VALUES
((SELECT id FROM regulation WHERE title='中华人民共和国刑法' LIMIT 1), '第一条', '为了惩罚犯罪，保护人民，根据宪法，结合我国同犯罪作斗争的具体经验及实际情况，制定本法。'),
((SELECT id FROM regulation WHERE title='中华人民共和国刑法' LIMIT 1), '第三条', '法律明文规定为犯罪行为的，依照法律定罪处刑；法律没有明文规定为犯罪行为的，不得定罪处刑。'),
((SELECT id FROM regulation WHERE title='中华人民共和国刑法' LIMIT 1), '第十三条', '一切危害国家主权、领土完整和安全，分裂国家、颠覆人民民主专政的政权和推翻社会主义制度，破坏社会秩序和经济秩序，侵犯国有财产或者劳动群众集体所有的财产，侵犯公民私人所有的财产，侵犯公民的人身权利、民主权利和其他权利，以及其他危害社会的行为，依照法律应当受刑罚处罚的，都是犯罪，但是情节显著轻微危害不大的，不认为是犯罪。'),
((SELECT id FROM regulation WHERE title='中华人民共和国刑法' LIMIT 1), '第十七条', '已满十六周岁的人犯罪，应当负刑事责任。已满十四周岁不满十六周岁的人，犯故意杀人、故意伤害致人重伤或者死亡、强奸、抢劫、贩卖毒品、放火、爆炸、投放危险物质罪的，应当负刑事责任。已满十二周岁不满十四周岁的人，犯故意杀人、故意伤害罪，致人死亡或者以特别残忍手段致人重伤造成严重残疾，情节恶劣，经最高人民检察院核准追诉的，应当负刑事责任。'),
((SELECT id FROM regulation WHERE title='中华人民共和国刑法' LIMIT 1), '第二百三十二条', '故意杀人的，处死刑、无期徒刑或者十年以上有期徒刑；情节较轻的，处三年以上十年以下有期徒刑。'),
((SELECT id FROM regulation WHERE title='中华人民共和国刑法' LIMIT 1), '第二百六十四条', '盗窃公私财物，数额较大的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；数额巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。');
INSERT INTO `regulation_article` (`regulation_id`, `article_no`, `content`) VALUES
((SELECT id FROM regulation WHERE title='最高人民法院关于审理民间借贷案件适用法律若干问题的规定' LIMIT 1), '第二十五条', '出借人请求借款人按照合同约定利率支付利息的，人民法院应予支持，但是双方约定的利率超过合同成立时一年期贷款市场报价利率四倍的除外。前款所称"一年期贷款市场报价利率"，是指中国人民银行授权全国银行间同业拆借中心自2019年8月20日起每月发布的一年期贷款市场报价利率。');
INSERT INTO `regulation_article` (`regulation_id`, `article_no`, `content`) VALUES
((SELECT id FROM regulation WHERE title='中华人民共和国消费者权益保护法' LIMIT 1), '第五十五条', '经营者提供商品或者服务有欺诈行为的，应当按照消费者的要求增加赔偿其受到的损失，增加赔偿的金额为消费者购买商品的价款或者接受服务的费用的三倍；增加赔偿的金额不足五百元的，为五百元。法律另有规定的，依照其规定。经营者明知商品或者服务存在缺陷，仍然向消费者提供，造成消费者或者其他受害人死亡或者健康严重损害的，受害人有权要求经营者依照本法第四十九条、第五十一条等法律规定赔偿损失，并有权要求所受损失二倍以下的惩罚性赔偿。');