-- ============================================================
-- 法智通 - 法规条文表（条文级全文）
-- 说明：本文件新建条文表并录入一批常见法规的条文全文作为起点。
--       更多法规/条文请通过 admin「法规管理」页面批量导入。
-- 执行: mysql> source d:/FAZHITONG/docs/seed-regulation-articles.sql
-- ============================================================
USE fazhitong;

CREATE TABLE IF NOT EXISTS `regulation_article` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `regulation_id` BIGINT NOT NULL COMMENT '法规ID',
    `article_no` VARCHAR(64) DEFAULT NULL COMMENT '条文序号/章节',
    `content` LONGTEXT COMMENT '条文全文',
    `create_time` DATETIME DEFAULT CURRENT_TIMESTAMP,
    INDEX idx_regulation (`regulation_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='法规条文';

